"""Primary deepTools/library evidence: retain operations, units and assay boundaries."""
import gzip,hashlib,json,re,xml.etree.ElementTree as ET
from pathlib import Path
from collect_omics_review import paragraphs
ROOT=Path(__file__).resolve().parents[2]
USES={
'P003':('Computed CUT&Run coverage after Cutadapt, local Bowtie2 mapping and SAMtools quality/duplicate/ENCODE-blacklist filtering; HOMER supplied the later1Mb IZ-centered average profiles.','The paragraph gives no deepTools version, coverage program or normalization. Do not assign HOMER profiles or BEDTools RNA/ATAC summaries to deepTools.'),
'P013':('Generated RPGC1x tracks with bamCoverage,10bp bins and extendReads, excluding chromosomeX from normalization. Used center-referenced10bp matrix bins over±1kb, original region order, missing-as-zero and per-bin sums; plotHeatmap/plotProfile rendered matrices. bigwigCompare subtracted RPGC input from H1 signal.','ChromosomeX exclusion affects the denominator, not necessarily track omission. Keep extended-read/fragment estimation, blacklist and sum-versus-mean choices explicit. TSS-ID joins excluded4-5percent unmatched genes; Micro-C junction coverage came from BEDTools. Source naming DeepTools2 alone is not an exact version.'),
'P020':('Used deepTools2.5.3 within ChIP_Zwart0.1.2 for reported FRiP/normalized ChIP-seq signal and tornado plots; bigwigCompare averaged RPGC1x replicate tracks within each condition.','Supply the actual FRiP counting unit/peak universe, effective genome, fragment rules and averaging operation. The paragraph does not identify its FRiP command. MACS2,DiffBind,ChIPSeeker,GIGGLE/Cistrome and Rseb remain separate.'),
'P032':('Used deepTools3.5.5 computeMatrix scale-regions with3kb upstream/downstream,5kb scaled gene bodies and skipZeros, followed by plotProfile perGroup, on scaled STAT5A ChIP-seq bigWigs and expressed-gene BED regions.','The expressed-gene universe used AAVS1 Teff RNA-seq baseMean>10. Scaling gene bodies changes bin geometry; skipZeros and per-group profiles must be retained. rtracklayer/ggplot smoothing and gene annotation are separate.'),
'P044':('Used deepTools3.5.1 bamCoverage for ATAC/CUT&Tag tracks and separate correlation analysis. R-loop CUT&Tag tracks were normalized as reads per million before metaplots; the ATAC pipeline separately applied strand-specificTn5 shifts.','Do not infer an unspecified normalization for ordinary ATAC/CUT&Tag or assign ComplexHeatmap rendering to deepTools. Maintain distinct assays, mapped-read units, mitochondrial/Y exclusion and duplicate/Tn5 preprocessing.'),
'P046':('Used deepTools3.5.1 multiBamSummary to summarize reads in a merged peak universe across four ATAC-seq cell types, then clustered samples using Spearman correlations.','The common region universe, read/fragment and filtering choices determine the correlation inputs. ENCODE preprocessing, FRiP/TSS QC, consensus-peak selection and DiffBind/DESeq2 are separate.'),
'P050':('Used computeMatrix reference-point with minThreshold2,10bp bins and averageTypeBins sum for T.gondii ChIP/ATAC gene-centered analysis, followed by profiles/heatmaps and optional k-means. ATAC BAMs were converted with bamCoverage using5bp bins.','Supply reference-point/flank/strand and clustering choices that the paragraph leaves unspecified. A per-bin sum is not a mean; retain the actual threshold/filter behavior. ChIP tracks originated in MACS2 bedGraph and UCSC conversion; nf-core peak/count/DE comparisons are separate.'),
'P061':('Used deepTools3.5.1 to profile chromosome-domain boundary probabilities at transcripts over±2Mb with25kb bins.','These are supplied boundary-probability tracks, not read counts. qnorm normalization, transcript grouping, within-subclass100000permutations, normal-tail approximation and GO backgrounds are separate.'),
'P065':('Generated RPGC-normalized ATAC and ChIP bigWigs with deepTools3.5.0 bamCoverage after BWA-MEM2 alignment to ordinary/custom hg38 and SAMtools cleanup. A different paragraph uses the pyBigWig stats library for fly-window means.','Keep the custom integrated-sequence reference/effective genome explicit. The deeptools/pyBigWig author namespace does not identify a deepTools stats command; the library API has its own catalog entry.'),
'P073':('Used deepTools3.5.1 to visualize read distribution after STARsolo two-pass/WASP alignment, barcode/UMI-aware duplicate handling and selection of unique proper pairs passing WASP.','The visualization program/normalization is unspecified. Barcode/UMI/WASP processing, merged-exon coverage and filtering must not be inferred from bamCoverage.'),
'P080':('Normalized sorted/indexed ATAC-seq and ChIPmentation BAMs as RPKM and converted them to bigWig with deepTools3.5.6 for UCSC browser views.','Retain read/fragment counting, bin width, reference and mapped-depth denominator. Bowtie2-k2 mapping does not itself establish unique alignments; longer Hba-alt ATAC reads are a separate library choice.'),
'P081':('Used deepTools3.5.1 for profiles,heatmaps and correlation matrices; supplied scores were averaged in nonoverlapping50bp reference-point bins and plotted as means.','Source tracks were built with BEDTools genomecov and separately fraction-normalized or spike-in calibrated by assay. Preserve that scaling; SEACR peaks, GraphPad violin plots and ROUT outlier removal atQ0.2percent are separate.'),
'P098':('Used deepTools3.5.0 bamCoverage for browser tracks and reference-point promoter profiles overTSS±5kb with skipZeros disabled. State bedGraphs were divided by sample number to represent chromatin-state percentages.','Keep precomputed ChromHMM state percentages distinct from BAM coverage. Preserving zero rows affects the promoter average; track-hub assembly and browser visualization are separate.'),
'P110':('Used DeepTools2 version3.5.0 to visualize average methylation around genes,TSS and transposable elements from bigWig tracks stratified by dinucleotide context, after Guppy/Rerio modified-base calling and modbam2bed.','These are supplied methylation values rather than ordinary read coverage. The matrix/window/strand and missing-call policies are unspecified; do not infer zero methylation for unobserved calls or silently generate BAM-depth tracks.'),
'P113':('Used deepTools with UCSC bigWigMerge to generate gene-track bigWigs using scaling factors obtained from sense-transcript DESeq2 analysis.','The exact deepTools command and merge operation are unspecified. Do not replace DGE-derived factors with generic CPM/RPGC or conflate track generation with antisense counts, manual review or bias correction.'),
'P124':('Generated CPM-normalized ATAC-seq bigWigs with deepTools3.0.1 bamCoverage after Bowtie1,blacklist and duplicate filtering.','The same paper has a separate RNA-seq pipeline. Preserve strand/library/read units and exact reference; peaks,union-peak featureCounts,DESeq2 and motif enrichment are separate.'),
'P133':('Used deepTools3.5.4 bamCoverage with RPGC for ChIP-seq and computeMatrix/plotHeatmap around genomic features. Separate ATAC preprocessing used alignmentSieve ATACshift in deepTools3.3.2, applying+4/-5 read-start shifts.','Preserve assay-specific versions and proper-pair/fragment/strand semantics. Shifted BAM records, MACS2BAMPE peaks and Rsubread paired-fragment counts are separate outputs; ordinary coverage must not silently applyTn5 shifts.'),
'P139':('Converted sorted/indexed GM12878 ATAC BAMs to bigWig with deepTools3.5.0 bamCoverage; downstream enhancer accessibility summed counts in±350bp around peak centers.','The source combined read1/read2 FASTQs before BWA-MEM mapping; do not silently reinterpret them as a paired-fragment BAM. Coverage normalization/bin width is unspecified; enhancer summation is a separate operation.'),
'P171':('Converted filtered CENH3 ChIP-seq BAMs to normalized bigWig with deepTools3.5.5 defaults for visualization.','The paragraph does not identify the command or normalization mode; defaults are version specific. Preserve the preceding literal Trimmomatic order, Bowtie2 filtering, MACS3BAMPE peaks and centromere merging as separate steps.'),
'P181':('Converted STAR2.7.11b Geuvadis RNA-seq BAMs to bigWig with deepTools bamCoverage using binSize1; other cohorts reused downloaded recount3 bigWigs.','Do not imply allGTEx/TCGA tracks were regenerated. Pantry alignment settings and subsequent pyBigWig bin means, median-depth scaling,pseudocount8/log2 and LaDDR are distinct.'),
'P215':('Listed deepTools among statistical-analysis software after Kallisto quantification and DESeq2; the paragraph does not identify a deepTools command or settings.','Retain this limited execution description rather than assigning a coverage/peak workflow. Raw gene counts were used for DESeq2, while TPMs were used for gene violin plots.')}
SUPPORT={'P013':[94,96,97,98],'P044':[51,54,57],'P050':[47],'P065':[72],'P098':[36],'P133':[40]}
EXTRA=[('pybigwig','pyBigWig',r'pyBigWig','Indexed bigWig/bigBed library access and interval summaries'),('qnorm','qnorm',r'(?-i:qnorm)','Quantile normalization of numeric matrices'),('ucsc-bigwigmerge','UCSC bigWigMerge',r'bigWigMerge','Merge bigWig tracks into a bedGraph signal')]
def main():
    papers={p['paper_id']:p for p in json.loads((ROOT/'docs/literature/omics-2023-2026/papers.json').read_text(encoding='utf-8'))};cached=json.loads((ROOT/'build/literature-review/track-trimming-runtime/paper-evidence.json').read_text(encoding='utf-8'));primary={x['paper_id']:x['source']['paragraph_index'] for x in cached if x['tool']=='deeptools'};primary['P110']=41;assert set(primary)==set(USES);primary['P065']=70
    registry_path=Path(__file__).with_name('tool-registry.json');registry=json.loads(registry_path.read_text(encoding='utf-8'));ids={x['id'] for x in registry}
    for tid,name,pattern,role in EXTRA:
        if tid not in ids:registry.append(dict(id=tid,name=name,pattern=r'(?<![A-Za-z0-9_])(?:'+pattern+r')(?![A-Za-z0-9_])',role=role,current_coverage='missing',existing_source=None,coverage_note='Distinct source-named library/program; integration and independent scientific validation pending.'))
    next(t for t in registry if t['id']=='deeptools')['pattern']=r'(?<![A-Za-z0-9_])(?:deepTools2?)(?![A-Za-z0-9_])'
    patterns={x['id']:x['pattern'] for x in registry};source={};rows=[]
    for pid in USES:
        p=papers[pid];raw=gzip.decompress((ROOT/'build/literature-review/xml'/f"{p['pmcid']}.xml.gz").read_bytes());assert hashlib.sha256(raw).hexdigest()==p['xml_sha256'];source[pid]=paragraphs(ET.fromstring(raw))
    def add(pid,tid,index,summary,note,support=()):
        p=papers[pid];e=source[pid][index-1];assert e['paragraph_index']==index and re.search(patterns[tid],e['match_text'],re.I),(pid,tid,index);row=dict(pmcid=p['pmcid'],doi=p['doi'],tool_id=tid,evidence_paragraph_sha256=hashlib.sha256(e['text'].encode()).hexdigest(),use_summary=summary,implementation_scope_note=note)
        if support:row['supporting_evidence']=[dict(paragraph_index=i,section=source[pid][i-1]['section'],paragraph_sha256=hashlib.sha256(source[pid][i-1]['text'].encode()).hexdigest()) for i in support]
        rows.append(row)
    for pid,(summary,note) in USES.items():add(pid,'deeptools',primary[pid],summary,note,SUPPORT.get(pid,()))
    add('P065','pybigwig',next(x['source']['paragraph_index'] for x in cached if x['tool']=='deeptools' and x['paper_id']=='P065'),'Used pyBigWig stats to obtain mean fly-genome accessibility for500bp windows at50bp stride when comparing DeepFlyBrain predictions with measured accessibility.','The source names deeptools/pyBigWig as the library repository. Exact-versus-zoom summaries and missing-base handling are unspecified; do not assume zero-filled exact means or a deepTools stats CLI.')
    add('P181','pybigwig',7,'Summarized base-level coverage into per-bin sample means with pyBigWig, then depth-scaled relative to the median sample, added pseudocount8 by default and log2-transformed for LaDDR phenotypes.','Library interval summaries are distinct from the downstream median-depth scaling, log transform and LaDDR model; the exact access/missing-data policy must be reconstructed separately.')
    add('P061','qnorm',primary['P061'],'Used qnorm0.8.0 to quantile-normalize transcript-body methylation fractions and25kb boundary probabilities along cell subclasses before differential/Pearson analyses.','Declare the actual matrix axis, ties and missing-data policy. The100000within-subclass genomic permutations,normal-tail P-values,FDR and length-matched GO background are separate from quantile normalization.')
    add('P113','ucsc-bigwigmerge',primary['P113'],'Used UCSC bigWigMerge together with deepTools for gene-track bigWigs using scaling factors derived from sense-transcript DESeq2.','The paragraph leaves the exact sequencing of scaling,merging and bigWig conversion unspecified. UCSC bigWigMerge produces bedGraph; do not infer replicate averaging, a ratio or an automatic binary-output conversion.')
    p=Path(__file__).with_name('reviewed-uses.json');d=json.loads(p.read_text(encoding='utf-8'));old={(x['pmcid'],x['tool_id']):x for x in d['reviews']};added=0;updated=0
    history=ROOT/'build/literature-review/catalog-history';history.mkdir(exist_ok=True);previous=history/(hashlib.sha256(p.read_bytes()).hexdigest()+'-reviewed-uses.json.gz')
    if not previous.exists():previous.write_bytes(gzip.compress(p.read_bytes(),mtime=0))
    for row in rows:
        key=row['pmcid'],row['tool_id']
        if key in old:
            if old[key]!=row:
                assert key==('PMC10719113','deeptools') and old[key]['evidence_paragraph_sha256']==row['evidence_paragraph_sha256'] and old[key]['use_summary']=='Profiled boundary probabilities across transcript-centered genomic windows.',key
                d['reviews'][d['reviews'].index(old[key])]=row;updated+=1
        else:d['reviews'].append(row);added+=1
    registry_path.write_text(json.dumps(registry,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(json.dumps(dict(added_reviews=added,updated_reviews=updated,total_reviews=len(d['reviews']),registry_names=len(registry))))
if __name__=='__main__':main()
